# SPDX-License-Identifier: Apache-2.0
"""The Grafana dashboards (deploy/observability/dashboards, generated by
tools/gen_dashboards.py) are the operator's view of the §11.1 catalog. A panel over a
misspelled or unexported series shows "No data" exactly when it is needed, and a counter
graphed without rate() looks like a flat line. So, statically:

* the committed JSON is what the generator produces;
* every series a query reads exists: a catalog metric (as Ray exports it), a Ray native
  series verified on the pinned Ray, or a recording rule of alerts.yaml;
* counters are read through rate()/increase(), histograms through their _bucket series,
  gauges never through rate();
* every catalog metric is on some panel, except the recorded, accepted gaps.
PromQL syntax is checked by promtool (qualification/check_alerts.sh)."""

from __future__ import annotations

import importlib.util
import json
import re
from pathlib import Path

import yaml

from raysimbatch.telemetry.metrics import CATALOG

ROOT = Path(__file__).resolve().parents[2]
OBS = ROOT / "deploy" / "observability"
spec = importlib.util.spec_from_file_location("gen_dashboards", ROOT / "tools" / "gen_dashboards.py")
gen = importlib.util.module_from_spec(spec)
spec.loader.exec_module(gen)

# Catalog metrics without a panel, and why (docs/operations/observability.md).
ACCEPTED_GAPS = {"native_arena_peak_bytes": "MJBatch's public bind() has no arena-usage field (probed: unknown field)"}
DERIVED = {"object_store_used_bytes", "object_store_capacity_bytes", "object_spilled_bytes_total",
           "object_restored_bytes_total"}  # recording rules raysimbatch:<name> over Ray native series


def recording_rules() -> set[str]:
  doc = yaml.safe_load((OBS / "alerts.yaml").read_text())
  return {r["record"] for g in doc["groups"] for r in g["rules"] if "record" in r}


def native_series() -> set[str]:
  return {ln.strip() for ln in (OBS / "ray-2.58.0-native-metrics.txt").read_text().splitlines()
          if ln.strip() and not ln.startswith("#")}


def test_committed_dashboards_are_generated():
  assert gen.main(["--check"]) == 0


def test_every_query_reads_existing_series_the_right_way():
  rules, native, bad = recording_rules(), native_series(), []
  for dash, title, expr in gen.expressions():
    where = f"{dash} / {title}: {expr}"
    for name, suffix in re.findall(r"\bray_raysimbatch_([a-z0-9_]+?)(_bucket|_count|_sum)?\b", expr):
      kind = CATALOG.get(name)
      if kind is None:
        bad.append(f"not in the catalog: {name} ({where})")
      elif kind == "histogram" and suffix != "_bucket":
        bad.append(f"histogram {name} read without _bucket ({where})")
      elif kind == "counter" and not re.search(rf"\b(rate|increase)\(ray_raysimbatch_{name}\b", expr):
        bad.append(f"counter {name} read without rate/increase ({where})")
      elif kind == "gauge" and re.search(rf"\b(rate|increase)\(ray_raysimbatch_{name}\b", expr):
        bad.append(f"gauge {name} read through rate ({where})")
    for rec in re.findall(r"\b(raysimbatch:[a-z0-9_]+)", expr):
      if rec not in rules:
        bad.append(f"no recording rule {rec} ({where})")
    for series in re.findall(r"\b(ray_(?!raysimbatch_)[a-z_]+)", expr):
      if series not in native:
        bad.append(f"not a verified Ray native series: {series} ({where})")
  assert not bad, "\n".join(bad)


def test_every_catalog_metric_is_on_a_panel():
  text = " ".join(e for _, _, e in gen.expressions())
  missing = []
  for name in CATALOG:
    if name in ACCEPTED_GAPS:
      continue
    if name in DERIVED:
      if f"raysimbatch:{name}" not in text:
        missing.append(name)
    elif not re.search(rf"\bray_raysimbatch_{name}(_bucket|_count|_sum)?\b", text):
      missing.append(name)
  assert not missing, missing


def test_dashboards_are_well_formed():
  for path in sorted((OBS / "dashboards").glob("*.json")):
    d = json.loads(path.read_text())
    ids = [p["id"] for p in d["panels"]]
    assert len(ids) == len(set(ids)), path.name
    assert d["uid"].startswith("rsb-") and "raysimbatch" in d["tags"]
    for p in d["panels"]:
      assert {"h", "w", "x", "y"} <= set(p["gridPos"]), (path.name, p["title"])
      for t in p.get("targets", ()):
        assert t["datasource"] == {"type": "prometheus", "uid": "${datasource}"} and t["expr"], (path.name, p["title"])
